spec.query:
import "strings"

from(bucket: "venus")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "platform/Notifications/NumberOfActiveAlarms" or r["_measurement"] == "platform/Notifications/NumberOfActiveInformations" or r["_measurement"] == "platform/Notifications/NumberOfActiveNotifications" or r["_measurement"] == "platform/Notifications/NumberOfActiveWarnings")
  |> aggregateWindow(every: v.windowPeriod, fn: mean, createEmpty: false)
  |> drop(columns: ["_field", "instanceNumber", "name", "portalId"])
  |> map(fn: (r) => ({
      r with
      _measurement: strings.trimPrefix(
          v: r._measurement,
          prefix: "platform/Notifications/NumberOfActive"
      )
  }))

